 64→const AIPromptsTab = () => {
 65→  const { user } = useAuth();
 66→  const qc = useQueryClient();
 67→  const [config, setConfig] = useState<RankingConfig | null>(null);
 68→  const [loading, setLoading] = useState(true);
 69→  const [saving, setSaving] = useState(false);
 70→  const [activeTab, setActiveTab] = useState<"config" | "studio">("config");
 71→  const [studioType, setStudioType] = useState<PromptType>("jd_analysis");
 72→  const [showHistory, setShowHistory] = useState(false);
 73→  const [compareIds, setCompareIds] = useState<[string, string] | null>(null);
 74→  const [testInput, setTestInput] = useState("");
 75→  const [testingId, setTestingId] = useState<string | null>(null);
 76→  const [newVersionDialog, setNewVersionDialog] = useState(false);
 77→  const [newForm, setNewForm] = useState({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });
 78→
 79→  useEffect(() => { fetchConfig(); }, []);
 80→
 81→  const fetchConfig = async () => {
 82→    const { data, error } = await supabase
 83→      .from("ranking_config")
 84→      .select("id, model, temperature, max_resume_chars, num_interview_questions, jd_analysis_prompt, resume_parse_prompt, deep_scoring_prompt, updated_at")
 85→      .limit(1).single();
 86→    if (error) toast.error("Error loading config: " + error.message);
 87→    else setConfig(data as unknown as RankingConfig);
 88→    setLoading(false);
 89→  };
 90→
 91→  const { data: versions, isLoading: versionsLoading } = useQuery({
 92→    queryKey: ["prompt_versions", studioType],
 93→    queryFn: async () => {
 94→      const { data, error } = await supabase
 95→        .from("prompt_versions")
 96→        .select("*")
 97→        .eq("prompt_type", studioType)
 98→        .order("created_at", { ascending: false });
 99→      if (error) throw error;
100→      return data as PromptVersion[];
101→    },
102→  });
103→
104→  const handleSaveConfig = async () => {
105→    if (!config) return;
106→    setSaving(true);
107→    const { id, updated_at, ...updates } = config;
108→    const { error } = await supabase.from("ranking_config").update(updates as any).eq("id", id);
109→    setSaving(false);
110→    if (error) toast.error(error.message);
111→    else { toast.success("Configuration saved"); fetchConfig(); }
112→  };
113→
114→  const handleResetConfig = () => {
115→    if (!config) return;
116→    setConfig({
117→      ...config, model: "gpt-4o-mini", temperature: 0.2, max_resume_chars: 4000, num_interview_questions: 5,
118→      jd_analysis_prompt: DEFAULT_PROMPTS.jd_analysis,
119→      resume_parse_prompt: DEFAULT_PROMPTS.resume_parse,
120→      deep_scoring_prompt: DEFAULT_PROMPTS.deep_scoring,
121→    });
122→  };
123→
124→  const updateConfig = (field: keyof RankingConfig, value: any) => {
125→    if (config) setConfig({ ...config, [field]: value });
126→  };
127→
128→  const createVersion = async () => {
129→    if (!newForm.label || !newForm.prompt_text) { toast.error("Label and prompt text are required"); return; }
130→    const { error } = await supabase.from("prompt_versions").insert({
131→      prompt_type: studioType,
132→      label: newForm.label,
133→      prompt_text: newForm.prompt_text,
134→      model: newForm.model,
135→      temperature: newForm.temperature,
136→      notes: newForm.notes,
137→      created_by: user?.id,
138→    } as any);
139→    if (error) { toast.error(error.message); return; }
140→    toast.success("Version created");
141→    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
142→    setNewVersionDialog(false);
143→    setNewForm({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });
144→  };
145→
146→  const activateVersion = async (v: PromptVersion) => {
147→    // Deactivate all, activate selected
148→    await supabase.from("prompt_versions").update({ is_active: false } as any).eq("prompt_type", studioType);
149→    await supabase.from("prompt_versions").update({ is_active: true } as any).eq("id", v.id);
